generate.final_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName WHERE {
  {
    SELECT DISTINCT ?investor WHERE {
      ?investor wm:hasCashFlow ?cf .
      ?cf wm:hasCashFlowSource ?cfs .
      ?cfs rdfs:label ?cfsLabel .
      FILTER(CONTAINS(LCASE(STR(?cfsLabel)), "net banking"))
    }
  }
  {
    SELECT DISTINCT ?investor WHERE {
      ?investor wm:hasHolding ?hold .
      ?hold wm:hasSector ?holdSector .
      ?holdSector rdfs:label ?holdSectorLabel .
      FILTER(CONTAINS(LCASE(STR(?holdSectorLabel)), "corporate"))
    }
  }
  {
    SELECT DISTINCT ?investor WHERE {
      ?investor wm:hasSectorAllocation ?alloc .
      ?alloc wm:hasSector ?allocSector .
      ?allocSector rdfs:label ?allocSectorLabel .
      FILTER(CONTAINS(LCASE(STR(?allocSectorLabel)), "corporate"))
    }
  }
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }
}

